#!/usr/bin/env python3
from __future__ import annotations

import json
import os
import socket
import socketserver
import struct
import hashlib
from datetime import datetime, timezone
from pathlib import Path
from typing import Any

from .research_db import FailClosed, ResearchDB, ResearchError, runtime_info
from .authority_runtime import DaemonContext
from .authority_store import AuthorityStore


ROOT = Path(os.environ.get("RESEARCHCTLD_ROOT", "/data/k3/research"))
SOCKET = Path(os.environ.get("RESEARCHCTLD_SOCKET", "/run/researchctl/control.sock"))
OWNER_ID = os.environ.get("RESEARCHCTLD_OWNER_ID", "k3-research-owner")
MAX_REQUEST_BYTES = 1024 * 1024


def beneath(path: str, allowed_root: Path) -> str:
    target = Path(path).resolve()
    base = allowed_root.resolve()
    if os.path.commonpath((str(target), str(base))) != str(base):
        raise FailClosed(f"path escapes allowed root: {allowed_root}")
    return str(target)


def daemon_context(peer_pid: int, peer_uid: int) -> DaemonContext:
    try:
        start_ticks = Path(f"/proc/{peer_pid}/stat").read_text().split()[21]
    except (OSError, IndexError) as exc:
        raise FailClosed("immutable peer session unavailable") from exc
    session_id = hashlib.sha256(f"{peer_uid}:{peer_pid}:{start_ticks}".encode()).hexdigest()
    recorded = datetime.now(timezone.utc).isoformat(timespec="microseconds").replace("+00:00", "Z")
    sequence = int(datetime.now(timezone.utc).timestamp() * 1_000_000)
    return DaemonContext(peer_uid, session_id, recorded, sequence)


def dispatch(request: dict[str, Any], peer_uid: int, peer_pid: int = -1) -> dict[str, Any]:
    if peer_uid < 0:
        raise FailClosed("authenticated Unix peer identity is unavailable")
    command = request.get("command")
    db = ResearchDB(ROOT)
    authority = AuthorityStore(ROOT / "research.sqlite")
    ctx = daemon_context(peer_pid, peer_uid) if peer_pid >= 0 else None
    if command == "runtime-info":
        return runtime_info()
    if command == "verify":
        return db.verify()
    if command == "rebuild-check":
        return db.rebuild_check()
    if command == "record":
        if request.get("actor_owner_id") != OWNER_ID:
            raise FailClosed("AUTHENTICATED_OWNER_MISMATCH")
        payload = request.get("payload")
        if not isinstance(payload, dict):
            raise FailClosed("payload must be an object")
        if request.get("entity_type") == "campaign" and payload.get("owner_id") != OWNER_ID:
            raise FailClosed("campaign owner must match authenticated Unix owner mapping")
        return db.record(str(request.get("entity_type")), payload, str(request.get("operation_id")), OWNER_ID)
    if command == "as-of":
        return db.pit(str(request.get("research_campaign_id")), str(request.get("as_of")), request.get("entity_type"))
    if command == "export-ledger":
        output = beneath(str(request.get("output")), ROOT / "exports")
        return db.export_ledger(output)
    if command == "backup-verify":
        backup = beneath(str(request.get("backup")), ROOT / "backups")
        restore = beneath(str(request.get("restore")), ROOT / "backups")
        return db.backup_verify(backup, restore)
    if command == "authority-propose":
        return authority.proposal(request["payload"], ctx)
    if command == "authority-transition":
        return authority.transition(str(request["proposal_id"]), str(request["target"]), ctx, request.get("observed_binding_sha256"))
    if command == "delegation-register":
        return authority.register_delegation(request["payload"], ctx)
    if command == "delegation-redeem":
        return authority.redeem(str(request["delegation_id"]), request["proposal"], ctx)
    if command == "delegation-revoke":
        return authority.revoke(str(request["delegation_id"]), ctx)
    if command == "amendment-register":
        return authority.register_amendment(str(request["delegation_id"]), str(request["amendment_id"]), str(request["amendment_sha256"]), ctx)
    raise FailClosed(f"daemon command is not allowlisted: {command}")


class Handler(socketserver.StreamRequestHandler):
    def handle(self) -> None:
        try:
            raw = self.rfile.readline(MAX_REQUEST_BYTES + 1)
            if not raw or len(raw) > MAX_REQUEST_BYTES or not raw.endswith(b"\n"):
                raise FailClosed("invalid request framing or size")
            request = json.loads(raw)
            if not isinstance(request, dict):
                raise FailClosed("request must be a JSON object")
            credentials = self.request.getsockopt(socket.SOL_SOCKET, socket.SO_PEERCRED, struct.calcsize("3i"))
            peer_pid, peer_uid, _ = struct.unpack("3i", credentials)
            result = dispatch(request, peer_uid, peer_pid)
            response = {"ok": True, "result": result, "peer_uid": peer_uid}
        except (ResearchError, OSError, ValueError, json.JSONDecodeError) as exc:
            response = {"ok": False, "error_code": getattr(exc, "code", exc.__class__.__name__.upper()), "error": str(exc)}
        except BaseException as exc:
            response = {"ok": False, "error_code": "INTERNAL_ERROR", "error": f"{exc.__class__.__name__}: {exc}"}
        self.wfile.write((json.dumps(response, ensure_ascii=False, sort_keys=True) + "\n").encode("utf-8"))


class Server(socketserver.ThreadingUnixStreamServer):
    daemon_threads = True
    allow_reuse_address = True


def main() -> int:
    health = ResearchDB(ROOT).verify()
    if health.get("status") != "PASS":
        raise FailClosed("production Research Memory preflight failed")
    if SOCKET.exists():
        SOCKET.unlink()
    SOCKET.parent.mkdir(parents=True, exist_ok=True)
    with Server(str(SOCKET), Handler) as server:
        os.chmod(SOCKET, 0o660)
        server.serve_forever(poll_interval=0.2)
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

from __future__ import annotations

import hashlib
import json
import os
import random
import shutil
import time
from contextlib import contextmanager
from datetime import datetime, timezone
from pathlib import Path
from typing import Any, Callable, Iterator

try:
    import apsw
except ImportError as exc:  # pragma: no cover - the formal launcher hard-pins APSW
    raise RuntimeError("researchctl requires the pinned APSW runtime") from exc


SCHEMA_VERSION = 2
WORKLOAD = "NON_STATISTICAL_INFRA_CANARY"
STATISTICAL_TRIAL_AUTHORITY = "NONE"
ALPHA_DISCOVERY_AUTHORITY = "NONE"
BUSY_TIMEOUT_MS = 2_000
MAX_WRITE_ATTEMPTS = 8
DOMAIN_TABLES = (
    "research_campaigns", "works", "versions", "locations", "claims",
    "contradictions", "hypotheses", "hypothesis_claims", "agent_runs", "search_calls",
)


class ResearchError(RuntimeError):
    code = "RESEARCH_ERROR"


class FailClosed(ResearchError):
    code = "FAIL_CLOSED"


class AuthorizationDenied(FailClosed):
    code = "CROSS_OWNER_WRITE_DENIED"


class MaintenanceActive(FailClosed):
    code = "MAINTENANCE_ACTIVE"


class RuntimeGateFailed(FailClosed):
    code = "RUNTIME_GATE_FAILED"


def canonical_json(value: Any) -> str:
    return json.dumps(value, ensure_ascii=False, sort_keys=True, separators=(",", ":"), allow_nan=False)


def sha256_text(value: str) -> str:
    return hashlib.sha256(value.encode("utf-8")).hexdigest()


def sha256_file(path: Path) -> str:
    digest = hashlib.sha256()
    with path.open("rb") as stream:
        for chunk in iter(lambda: stream.read(1024 * 1024), b""):
            digest.update(chunk)
    return digest.hexdigest()


def utc_now() -> str:
    return datetime.now(timezone.utc).isoformat(timespec="microseconds").replace("+00:00", "Z")


def normalize_utc(value: str) -> str:
    if not isinstance(value, str) or not value.endswith("Z"):
        raise FailClosed("timestamp must be RFC3339 UTC with Z suffix")
    try:
        parsed = datetime.fromisoformat(value[:-1] + "+00:00")
    except ValueError as exc:
        raise FailClosed("invalid RFC3339 UTC timestamp") from exc
    if parsed.utcoffset() != timezone.utc.utcoffset(parsed):
        raise FailClosed("timestamp must be UTC")
    return parsed.astimezone(timezone.utc).isoformat(timespec="microseconds").replace("+00:00", "Z")


def _version_tuple(value: str) -> tuple[int, ...]:
    out: list[int] = []
    for part in value.split("."):
        digits = "".join(ch for ch in part if ch.isdigit())
        if not digits:
            break
        out.append(int(digits))
    return tuple(out)


def runtime_info() -> dict[str, Any]:
    apsw_version = apsw.apswversion()
    sqlite_version = apsw.sqlitelibversion()
    if _version_tuple(apsw_version) < (3, 53, 4) or _version_tuple(sqlite_version) < (3, 51, 3):
        raise RuntimeGateFailed(
            f"runtime too old: APSW={apsw_version}, SQLite={sqlite_version}; "
            "requires APSW>=3.53.4 and SQLite>=3.51.3"
        )
    probe = apsw.Connection(":memory:")
    try:
        source_id = probe.execute("SELECT sqlite_source_id()").fetchone()[0]
    finally:
        probe.close()
    return {
        "apsw_version": apsw_version,
        "sqlite_version": sqlite_version,
        "sqlite_source_id": source_id,
        "runtime_gate": "PASS",
    }


def filesystem_info(path: Path) -> dict[str, Any]:
    resolved = path.resolve()
    best: tuple[int, str, str] | None = None
    if os.name != "nt" and Path("/proc/mounts").exists():
        for line in Path("/proc/mounts").read_text(encoding="utf-8").splitlines():
            parts = line.split()
            if len(parts) < 3:
                continue
            mount = parts[1].replace("\\040", " ")
            try:
                relative = os.path.commonpath((str(resolved), mount)) == mount
            except ValueError:
                relative = False
            if relative and (best is None or len(mount) > best[0]):
                best = (len(mount), mount, parts[2])
    fstype = best[2] if best else "unknown"
    allowed_test = os.environ.get("RESEARCHCTL_ALLOW_TEST_FILESYSTEM") == "1"
    if not allowed_test:
        if not str(resolved).startswith("/data/k3/research"):
            raise FailClosed("formal Research Memory must remain under /data/k3/research")
        if fstype != "ext4":
            raise FailClosed(f"Research Memory requires local ext4, observed {fstype}")
        if not os.path.ismount("/data"):
            raise FailClosed("/data is not a real mount")
        if os.stat("/data").st_dev == os.stat("/").st_dev:
            raise FailClosed("/data and root filesystem are not distinct devices")
    if fstype.lower() in {"nfs", "nfs4", "cifs", "smbfs", "fuse.sshfs"}:
        raise FailClosed(f"network filesystem forbidden for SQLite WAL: {fstype}")
    return {
        "resolved_path": str(resolved),
        "mountpoint": best[1] if best else None,
        "filesystem_type": fstype,
        "test_override": allowed_test,
    }


def fsync_directory(path: Path) -> None:
    if os.name == "nt":
        return
    fd = os.open(path, os.O_RDONLY | getattr(os, "O_DIRECTORY", 0))
    try:
        os.fsync(fd)
    finally:
        os.close(fd)


@contextmanager
def file_lock(path: Path, exclusive: bool) -> Iterator[None]:
    path.parent.mkdir(parents=True, exist_ok=True)
    fd = os.open(path, os.O_RDWR | os.O_CREAT, 0o600)
    try:
        if os.name == "nt":
            import msvcrt
            if os.fstat(fd).st_size == 0:
                os.write(fd, b"\0")
            os.lseek(fd, 0, os.SEEK_SET)
            msvcrt.locking(fd, msvcrt.LK_LOCK, 1)
        else:
            import fcntl
            fcntl.flock(fd, fcntl.LOCK_EX if exclusive else fcntl.LOCK_SH)
        try:
            yield
        finally:
            if os.name == "nt":
                os.lseek(fd, 0, os.SEEK_SET)
                msvcrt.locking(fd, msvcrt.LK_UNLCK, 1)
            else:
                fcntl.flock(fd, fcntl.LOCK_UN)
    finally:
        os.close(fd)


def rows_with_names(cursor: Any, names: list[str] | tuple[str, ...]) -> list[dict[str, Any]]:
    return [dict(zip(names, row, strict=True)) for row in cursor]


def table_columns(con: Any, table: str) -> list[str]:
    safe = '"' + table.replace('"', '""') + '"'
    return [str(row[1]) for row in con.execute(f"PRAGMA table_xinfo({safe})")]


def table_rows(con: Any, table: str) -> list[dict[str, Any]]:
    safe = '"' + table.replace('"', '""') + '"'
    return rows_with_names(con.execute(f"SELECT * FROM {safe} ORDER BY 1"), table_columns(con, table))


ENTITY_SPECS: dict[str, dict[str, Any]] = {
    "campaign": {"table": "research_campaigns", "id": "research_campaign_id", "required": {"research_campaign_id", "owner_id", "campaign_name"}, "optional": set()},
    "work": {"table": "works", "id": "work_id", "required": {"work_id", "research_campaign_id", "canonical_key", "title"}, "optional": {"work_type"}},
    "version": {"table": "versions", "id": "version_id", "required": {"version_id", "research_campaign_id", "work_id", "version_key", "version_label"}, "optional": {"content_sha256"}},
    "location": {"table": "locations", "id": "location_id", "required": {"location_id", "research_campaign_id", "version_id", "source_kind", "source_key", "locator"}, "optional": {"content_sha256"}},
    "claim": {"table": "claims", "id": "claim_id", "required": {"claim_id", "research_campaign_id", "version_id", "claim_text"}, "optional": {"location_id", "claim_kind"}},
    "contradiction": {"table": "contradictions", "id": "contradiction_id", "required": {"contradiction_id", "research_campaign_id", "left_claim_id", "right_claim_id", "rationale"}, "optional": {"relation_kind"}},
    "hypothesis": {"table": "hypotheses", "id": "hypothesis_id", "required": {"hypothesis_id", "research_campaign_id", "hypothesis_text"}, "optional": {"status"}},
    "hypothesis_claim": {"table": "hypothesis_claims", "id": "link_id", "required": {"link_id", "research_campaign_id", "hypothesis_id", "claim_id", "relation_kind"}, "optional": set()},
    "agent_run": {"table": "agent_runs", "id": "agent_run_id", "required": {"agent_run_id", "research_campaign_id", "task_name"}, "optional": {"status"}},
    "search_call": {"table": "search_calls", "id": "search_call_id", "required": {"search_call_id", "research_campaign_id", "agent_run_id", "provider", "request_digest"}, "optional": {"status"}},
}


DEFAULTS = {
    "work_type": "OTHER", "claim_kind": "ASSERTION", "relation_kind": "CONTRADICTS",
    "status": "PROPOSED",
}


class ResearchDB:
    def __init__(self, root: str | os.PathLike[str]):
        self.root = Path(root)
        self.db_path = self.root / "research.sqlite"
        self.lock_path = self.root / ".researchctl.lock"
        self.schema_path = Path(__file__).with_name("research_schema.sql")

    def _open(self, *, initialize: bool = False, memory: bool = False) -> Any:
        target = ":memory:" if memory else str(self.db_path)
        flags = apsw.SQLITE_OPEN_READWRITE | apsw.SQLITE_OPEN_CREATE if initialize or memory else apsw.SQLITE_OPEN_READWRITE
        con = apsw.Connection(target, flags=flags)
        try:
            con.set_busy_timeout(BUSY_TIMEOUT_MS)
            con.execute("PRAGMA foreign_keys=ON")
            if not memory:
                if initialize:
                    mode = str(con.execute("PRAGMA journal_mode=WAL").fetchone()[0]).lower()
                    if mode != "wal":
                        raise FailClosed(f"WAL unavailable: {mode}")
                else:
                    mode = str(con.execute("PRAGMA journal_mode").fetchone()[0]).lower()
                    if mode != "wal":
                        raise FailClosed(f"journal mode drift: {mode}")
            con.execute("PRAGMA synchronous=FULL")
            synchronous = int(con.execute("PRAGMA synchronous").fetchone()[0])
            if synchronous != 2:
                raise FailClosed(f"synchronous drift: {synchronous}")
            return con
        except BaseException:
            con.close()
            raise

    def initialize(self) -> dict[str, Any]:
        runtime = runtime_info()
        self.root.mkdir(parents=True, exist_ok=True)
        os.chmod(self.root, 0o750)
        fs = filesystem_info(self.root)
        with file_lock(self.lock_path, exclusive=True):
            con = self._open(initialize=True)
            try:
                objects = con.execute(
                    "SELECT name FROM sqlite_schema WHERE name NOT LIKE 'sqlite_%' ORDER BY name"
                ).fetchall()
                if objects:
                    if not any(row[0] == "schema_meta" for row in objects):
                        raise FailClosed("UNVERSIONED_NONEMPTY")
                    self._verify_schema_version(con)
                else:
                    con.execute("BEGIN IMMEDIATE")
                    try:
                        con.execute(self.schema_path.read_text(encoding="utf-8"))
                        con.execute("COMMIT")
                    except BaseException:
                        if not con.getautocommit():
                            con.execute("ROLLBACK")
                        raise
                self._verify_schema_version(con)
                integrity = con.execute("PRAGMA integrity_check").fetchall()
                if integrity != [("ok",)]:
                    raise FailClosed(f"integrity_check failed: {integrity[:3]}")
            finally:
                con.close()
            os.chmod(self.db_path, 0o640)
            for suffix in ("-wal", "-shm"):
                sidecar = Path(str(self.db_path) + suffix)
                if sidecar.exists():
                    os.chmod(sidecar, 0o640)
            fsync_directory(self.root)
        return {"status": "PASS", "schema_version": SCHEMA_VERSION, "database": str(self.db_path), "runtime": runtime, "filesystem": fs}

    @staticmethod
    def _verify_schema_version(con: Any) -> None:
        rows = con.execute("SELECT schema_version,schema_name FROM schema_meta WHERE singleton=1").fetchall()
        if rows != [(SCHEMA_VERSION, "k3-research-memory")]:
            raise FailClosed(f"unsupported schema metadata: {rows!r}")

    def _short_write(self, operation: Callable[[Any], dict[str, Any]], *, exclusive_file_lock: bool = False) -> dict[str, Any]:
        with file_lock(self.lock_path, exclusive=exclusive_file_lock):
            for attempt in range(MAX_WRITE_ATTEMPTS):
                con = self._open()
                began = False
                try:
                    self._verify_schema_version(con)
                    con.execute("BEGIN IMMEDIATE")
                    began = True
                    if con.execute("SELECT active FROM maintenance_state WHERE singleton=1").fetchone()[0]:
                        raise MaintenanceActive("Research Memory is in maintenance mode")
                    result = operation(con)
                    con.execute("COMMIT")
                    began = False
                    result["lock_retry_count"] = attempt
                    return result
                except (apsw.BusyError, apsw.LockedError):
                    if began and not con.getautocommit():
                        con.execute("ROLLBACK")
                    if attempt + 1 == MAX_WRITE_ATTEMPTS:
                        raise FailClosed("DATABASE_BUSY_RETRY_BUDGET_EXHAUSTED")
                    time.sleep(random.uniform(0, min(0.2, 0.01 * (2 ** attempt))))
                except BaseException:
                    if began and not con.getautocommit():
                        con.execute("ROLLBACK")
                    raise
                finally:
                    con.close()
        raise AssertionError("unreachable")

    def record(self, entity_type: str, payload: dict[str, Any], operation_id: str, actor_owner_id: str) -> dict[str, Any]:
        if entity_type not in ENTITY_SPECS:
            raise FailClosed(f"unsupported entity type: {entity_type}")
        if not isinstance(payload, dict):
            raise FailClosed("payload must be a JSON object")
        if not operation_id or not actor_owner_id:
            raise FailClosed("operation_id and actor_owner_id are required")
        spec = ENTITY_SPECS[entity_type]
        temporal = {"known_at", "backfilled", "backfill_source"}
        allowed = spec["required"] | spec["optional"] | temporal
        missing = spec["required"] - payload.keys()
        unknown = payload.keys() - allowed
        if missing or unknown:
            raise FailClosed(f"payload fields invalid; missing={sorted(missing)}, unknown={sorted(unknown)}")
        request = {"entity_type": entity_type, "payload": payload, "operation_id": operation_id, "actor_owner_id": actor_owner_id}
        request_sha = sha256_text(canonical_json(request))
        ingested_at = utc_now()
        known_input = payload.get("known_at")
        known_at = normalize_utc(known_input) if known_input is not None else ingested_at
        known_source = "AUTHORITATIVE" if known_input is not None else "INGESTED_AT_FALLBACK"
        backfilled = payload.get("backfilled", False)
        if type(backfilled) is not bool:
            raise FailClosed("backfilled must be a JSON boolean")
        backfill_source = payload.get("backfill_source")
        if backfilled != bool(backfill_source):
            raise FailClosed("backfilled must be true iff backfill_source is present")
        row = {key: value for key, value in payload.items() if key not in temporal}
        row.update({
            "known_at": known_at, "ingested_at": ingested_at, "known_at_source": known_source,
            "backfilled": int(backfilled), "backfill_source": backfill_source, "revision": 1,
        })
        if entity_type == "campaign":
            if row["owner_id"] != actor_owner_id:
                raise AuthorizationDenied("campaign owner does not match authenticated owner")
        else:
            row["owner_id"] = actor_owner_id
        if entity_type == "work":
            row.setdefault("work_type", "OTHER")
        elif entity_type == "claim":
            row.setdefault("location_id", None)
            row.setdefault("claim_kind", "ASSERTION")
        elif entity_type == "contradiction":
            row.setdefault("relation_kind", "CONTRADICTS")
            if row["right_claim_id"] < row["left_claim_id"]:
                row["left_claim_id"], row["right_claim_id"] = row["right_claim_id"], row["left_claim_id"]
        elif entity_type == "hypothesis":
            row.setdefault("status", "PROPOSED")
            row["assessment_mode"] = "NON_STATISTICAL"
        elif entity_type == "agent_run":
            row.setdefault("status", "CREATED")
            row.update({"workload": WORKLOAD, "statistical_trial_authority": STATISTICAL_TRIAL_AUTHORITY, "alpha_discovery_authority": ALPHA_DISCOVERY_AUTHORITY})
        elif entity_type == "search_call":
            row.setdefault("status", "NOT_EXECUTED")
        elif entity_type == "location":
            identity = {key: row.get(key) for key in ("research_campaign_id", "version_id", "source_kind", "source_key", "locator", "content_sha256")}
            row["dedup_key"] = sha256_text(canonical_json(identity))
        for field in ("content_sha256", "request_digest"):
            if row.get(field) is not None:
                value = row[field]
                if not isinstance(value, str) or len(value) != 64 or any(ch not in "0123456789abcdef" for ch in value):
                    raise FailClosed(f"{field} must be 64 lowercase hexadecimal characters")

        def write(con: Any) -> dict[str, Any]:
            previous = con.execute(
                "SELECT request_sha256,result_json FROM infrastructure_operations WHERE operation_id=?",
                (operation_id,),
            ).fetchone()
            if previous:
                if previous[0] != request_sha:
                    raise FailClosed("OPERATION_ID_CONFLICT")
                result = json.loads(previous[1])
                result["replayed"] = True
                return result
            campaign_id = row["research_campaign_id"]
            if entity_type != "campaign":
                campaign = con.execute(
                    "SELECT owner_id FROM research_campaigns WHERE research_campaign_id=?", (campaign_id,)
                ).fetchone()
                if campaign is None or campaign[0] != actor_owner_id:
                    raise AuthorizationDenied("campaign is absent or belongs to another owner")
            dedup = self._dedup_lookup(con, entity_type, row)
            if dedup is not None:
                result = {"status": "DEDUPLICATED", "entity_type": entity_type, "entity_id": dedup, "event_accepted": False, "replayed": False, "committed_at": ingested_at}
                con.execute(
                    "INSERT INTO infrastructure_operations VALUES(?,?,?,?,?,?,?)",
                    (operation_id, actor_owner_id, campaign_id, "RECORD_" + entity_type.upper(), request_sha, canonical_json(result), ingested_at),
                )
                return result
            columns = list(row)
            con.execute(
                f"INSERT INTO {spec['table']} ({','.join(columns)}) VALUES ({','.join('?' for _ in columns)})",
                tuple(row[column] for column in columns),
            )
            hook = os.environ.get("RESEARCHCTL_FAULT_READY_FILE")
            if hook:
                Path(hook).write_text("DOMAIN_WRITE_COMPLETE_UNCOMMITTED\n", encoding="utf-8")
                while True:
                    time.sleep(1)
            entity_id = str(row[spec["id"]])
            materialized = con.execute(
                f"SELECT * FROM {spec['table']} WHERE {spec['id']}=?", (entity_id,)
            ).fetchone()
            if materialized is None:
                raise FailClosed("inserted current-state row is not readable")
            materialized_row = dict(zip(table_columns(con, spec["table"]), materialized, strict=True))
            event_key = f"{operation_id}:CREATED"
            previous_hash_row = con.execute("SELECT event_hash FROM audit_events ORDER BY event_id DESC LIMIT 1").fetchone()
            previous_hash = previous_hash_row[0] if previous_hash_row else None
            payload_json = canonical_json(materialized_row)
            event_hash = sha256_text("|".join((previous_hash or "", event_key, entity_type, entity_id, known_at, ingested_at, payload_json)))
            con.execute(
                """INSERT INTO audit_events(
                    event_key,entity_type,entity_id,research_campaign_id,owner_id,actor_owner_id,
                    entity_revision,event_type,known_at,ingested_at,backfilled,backfill_source,
                    payload_json,previous_event_hash,event_hash,workload,statistical_trial_authority,
                    alpha_discovery_authority) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)""",
                (event_key, entity_type, entity_id, campaign_id, actor_owner_id, actor_owner_id,
                 1, "CREATED", known_at, ingested_at, int(backfilled), backfill_source, payload_json,
                 previous_hash, event_hash, WORKLOAD, STATISTICAL_TRIAL_AUTHORITY, ALPHA_DISCOVERY_AUTHORITY),
            )
            result = {"status": "CREATED", "entity_type": entity_type, "entity_id": entity_id, "event_accepted": True, "event_hash": event_hash, "replayed": False, "committed_at": ingested_at, "known_at": known_at, "known_at_source": known_source}
            con.execute(
                "INSERT INTO infrastructure_operations VALUES(?,?,?,?,?,?,?)",
                (operation_id, actor_owner_id, campaign_id, "RECORD_" + entity_type.upper(), request_sha, canonical_json(result), ingested_at),
            )
            return result

        return self._short_write(write)

    @staticmethod
    def _dedup_lookup(con: Any, entity_type: str, row: dict[str, Any]) -> str | None:
        if entity_type == "location":
            found = con.execute("SELECT location_id FROM locations WHERE research_campaign_id=? AND dedup_key=?", (row["research_campaign_id"], row["dedup_key"])).fetchone()
        elif entity_type == "work":
            found = con.execute("SELECT work_id FROM works WHERE research_campaign_id=? AND canonical_key=?", (row["research_campaign_id"], row["canonical_key"])).fetchone()
        elif entity_type == "search_call":
            found = con.execute("SELECT search_call_id FROM search_calls WHERE agent_run_id=? AND request_digest=?", (row["agent_run_id"], row["request_digest"])).fetchone()
        else:
            found = None
        return str(found[0]) if found else None

    def pit(self, campaign_id: str, as_of: str, entity_type: str | None = None) -> dict[str, Any]:
        cutoff = normalize_utc(as_of)
        con = self._open()
        try:
            params: list[Any] = [campaign_id, cutoff]
            predicate = "research_campaign_id=? AND known_at<=? AND event_type<>'MIGRATION'"
            if entity_type:
                if entity_type not in ENTITY_SPECS:
                    raise FailClosed("unknown PIT entity type")
                predicate += " AND entity_type=?"
                params.append(entity_type)
            pit_columns = ("entity_type", "entity_id", "entity_revision", "known_at", "ingested_at", "backfilled", "backfill_source", "payload_json", "event_hash")
            rows = rows_with_names(con.execute(
                f"""SELECT entity_type,entity_id,entity_revision,known_at,ingested_at,backfilled,
                    backfill_source,payload_json,event_hash FROM (
                    SELECT *,row_number() OVER(PARTITION BY entity_type,entity_id ORDER BY entity_revision DESC) AS rn
                    FROM audit_events WHERE {predicate}) WHERE rn=1 ORDER BY entity_type,entity_id""",
                tuple(params),
            ), pit_columns)
            for row in rows:
                row["payload"] = json.loads(row.pop("payload_json"))
            return {"status": "PASS", "research_campaign_id": campaign_id, "as_of": cutoff, "pit_time_axis": "known_at", "boundary": "CLOSED", "records": rows, "record_count": len(rows)}
        finally:
            con.close()

    def verify(self) -> dict[str, Any]:
        runtime = runtime_info()
        fs = filesystem_info(self.root)
        con = self._open()
        try:
            self._verify_schema_version(con)
            integrity_rows = con.execute("PRAGMA integrity_check").fetchall()
            foreign_rows = con.execute("PRAGMA foreign_key_check").fetchall()
            events = rows_with_names(con.execute("SELECT * FROM audit_events ORDER BY event_id"), table_columns(con, "audit_events"))
            previous: str | None = None
            chain_errors = 0
            scope_errors = 0
            duplicate_entity_events = int(con.execute(
                "SELECT count(*) FROM (SELECT entity_type,entity_id,entity_revision,count(*) c FROM audit_events GROUP BY 1,2,3 HAVING c>1)"
            ).fetchone()[0])
            for event in events:
                expected = sha256_text("|".join((previous or "", event["event_key"], event["entity_type"], event["entity_id"], event["known_at"], event["ingested_at"], event["payload_json"])))
                if event["previous_event_hash"] != previous or event["event_hash"] != expected:
                    chain_errors += 1
                if event["workload"] != WORKLOAD or event["statistical_trial_authority"] != "NONE" or event["alpha_discovery_authority"] != "NONE":
                    scope_errors += 1
                previous = event["event_hash"]
            current = self._projection(con)
            event_current_diff = self._event_current_diff(con, current)
            journal_mode = str(con.execute("PRAGMA journal_mode").fetchone()[0]).lower()
            synchronous = int(con.execute("PRAGMA synchronous").fetchone()[0])
            status = "PASS" if integrity_rows == [("ok",)] and not foreign_rows and not chain_errors and not scope_errors and not duplicate_entity_events and event_current_diff == 0 and journal_mode == "wal" and synchronous == 2 else "FAIL"
            return {
                "status": status, "runtime": runtime, "filesystem": fs, "integrity_check": [row[0] for row in integrity_rows],
                "foreign_key_violation_count": len(foreign_rows), "journal_mode": journal_mode,
                "synchronous": "FULL" if synchronous == 2 else synchronous, "busy_timeout_ms": BUSY_TIMEOUT_MS,
                "event_count": len(events), "event_chain_errors": chain_errors, "scope_errors": scope_errors,
                "duplicate_accepted_events": duplicate_entity_events, "event_current_rebuild_diff": event_current_diff,
                "projection_sha256": sha256_text(canonical_json(current)),
            }
        finally:
            con.close()

    @staticmethod
    def _projection(con: Any) -> dict[str, list[dict[str, Any]]]:
        return {table: table_rows(con, table) for table in DOMAIN_TABLES}

    @staticmethod
    def _event_current_diff(con: Any, current: dict[str, list[dict[str, Any]]]) -> int:
        expected: dict[str, dict[str, dict[str, Any]]] = {table: {} for table in DOMAIN_TABLES}
        type_to_table = {key: value["table"] for key, value in ENTITY_SPECS.items()}
        for entity_type, entity_id, payload_json in con.execute(
            """SELECT a.entity_type,a.entity_id,a.payload_json FROM audit_events a
               JOIN (SELECT entity_type,entity_id,max(entity_revision) rev FROM audit_events
                     WHERE event_type<>'MIGRATION' GROUP BY entity_type,entity_id) latest
               ON latest.entity_type=a.entity_type AND latest.entity_id=a.entity_id AND latest.rev=a.entity_revision"""
        ):
            table = type_to_table.get(entity_type)
            if table:
                expected[table][str(entity_id)] = json.loads(payload_json)
        actual = {table: {str(row[next(spec["id"] for spec in ENTITY_SPECS.values() if spec["table"] == table)]): row for row in rows} for table, rows in current.items()}
        return sum(1 for table in DOMAIN_TABLES if canonical_json(actual[table]) != canonical_json(expected[table]))

    def rebuild_check(self) -> dict[str, Any]:
        source = self._open()
        rebuilt = self._open(memory=True)
        try:
            source.execute("BEGIN")
            live = self._projection(source)
            events = rows_with_names(source.execute("SELECT entity_type,payload_json FROM audit_events WHERE event_type<>'MIGRATION' ORDER BY event_id"), ("entity_type", "payload_json"))
            rebuilt.execute("BEGIN IMMEDIATE")
            rebuilt.execute(self.schema_path.read_text(encoding="utf-8"))
            type_to_table = {key: value["table"] for key, value in ENTITY_SPECS.items()}
            for event in events:
                row = json.loads(event["payload_json"])
                table = type_to_table[event["entity_type"]]
                columns = list(row)
                rebuilt.execute(f"INSERT INTO {table} ({','.join(columns)}) VALUES ({','.join('?' for _ in columns)})", tuple(row[c] for c in columns))
            rebuilt.execute("COMMIT")
            shadow = self._projection(rebuilt)
            live_hash = sha256_text(canonical_json(live))
            shadow_hash = sha256_text(canonical_json(shadow))
            return {"status": "PASS" if live_hash == shadow_hash else "FAIL", "event_count": len(events), "live_projection_sha256": live_hash, "rebuilt_projection_sha256": shadow_hash, "diff": 0 if live_hash == shadow_hash else 1, "transactional_rebuild": True}
        finally:
            if not source.getautocommit():
                source.execute("ROLLBACK")
            source.close()
            rebuilt.close()

    def export_ledger(self, output: str | os.PathLike[str]) -> dict[str, Any]:
        path = Path(output)
        if path.exists():
            raise FailClosed("export target already exists")
        path.parent.mkdir(parents=True, exist_ok=True)
        con = self._open()
        try:
            con.execute("BEGIN")
            version = con.execute("SELECT schema_version FROM schema_meta WHERE singleton=1").fetchone()[0]
            events = rows_with_names(con.execute("SELECT * FROM audit_events ORDER BY event_id"), table_columns(con, "audit_events"))
            header = {"record_type": "header", "format": "research-ledger-jsonl", "version": 1, "schema_version": version, "authority": {"workload": WORKLOAD, "statistical_trial_authority": "NONE", "alpha_discovery_authority": "NONE"}}
            records: list[dict[str, Any]] = [header]
            for event in events:
                event = dict(event)
                event["payload"] = json.loads(event.pop("payload_json"))
                base = {"record_type": "event", "event": event}
                base["record_sha256"] = sha256_text(canonical_json(base))
                records.append(base)
            stream = "".join(canonical_json(item) + "\n" for item in records).encode("utf-8")
            trailer = {"record_type": "trailer", "event_count": len(events), "stream_sha256": hashlib.sha256(stream).hexdigest()}
            data = stream + (canonical_json(trailer) + "\n").encode("utf-8")
            temp = path.with_name(f".{path.name}.tmp-{os.getpid()}")
            with temp.open("xb") as out:
                out.write(data)
                out.flush()
                os.fsync(out.fileno())
            os.replace(temp, path)
            fsync_directory(path.parent)
            return {"status": "PASS", "path": str(path), "sha256": hashlib.sha256(data).hexdigest(), "stream_sha256": trailer["stream_sha256"], "event_count": len(events), "bytes": len(data)}
        finally:
            if not con.getautocommit():
                con.execute("ROLLBACK")
            con.close()

    @staticmethod
    def _schema_hash(con: Any) -> str:
        rows = con.execute("SELECT type,name,tbl_name,coalesce(sql,'') FROM sqlite_schema WHERE name NOT LIKE 'sqlite_%' ORDER BY type,name,tbl_name,coalesce(sql,'')").fetchall()
        return sha256_text(canonical_json(rows))

    @classmethod
    def _logical_manifest(cls, con: Any) -> dict[str, Any]:
        integrity = [row[0] for row in con.execute("PRAGMA integrity_check")]
        foreign = con.execute("PRAGMA foreign_key_check").fetchall()
        tables = [row[0] for row in con.execute("SELECT name FROM sqlite_schema WHERE type='table' AND name NOT LIKE 'sqlite_%' ORDER BY name")]
        counts: dict[str, int] = {}
        hashes: dict[str, str] = {}
        for table in tables:
            safe = '"' + table.replace('"', '""') + '"'
            rows = table_rows(con, table)
            counts[table] = len(rows)
            hashes[table] = sha256_text(canonical_json(rows))
        database_hash = sha256_text(canonical_json({"schema": cls._schema_hash(con), "counts": counts, "tables": hashes}))
        return {"integrity_check": integrity, "foreign_key_violation_count": len(foreign), "schema_sha256": cls._schema_hash(con), "table_counts": counts, "table_logical_sha256": hashes, "database_logical_sha256": database_hash}

    def backup_verify(self, backup_path: str | os.PathLike[str], restore_path: str | os.PathLike[str]) -> dict[str, Any]:
        backup = Path(backup_path)
        restore = Path(restore_path)
        if backup.exists() or restore.exists():
            raise FailClosed("backup and restore targets must not exist")
        backup.parent.mkdir(parents=True, exist_ok=True)
        restore.parent.mkdir(parents=True, exist_ok=True)
        with file_lock(self.lock_path, exclusive=False):
            source = self._open()
            try:
                source_before = self._logical_manifest(source)
                source.execute("VACUUM INTO ?", (str(backup),))
                source_after = self._logical_manifest(source)
            finally:
                source.close()
        backup_con = apsw.Connection(str(backup), flags=apsw.SQLITE_OPEN_READWRITE)
        try:
            backup_manifest = self._logical_manifest(backup_con)
        finally:
            backup_con.close()
        shutil.copyfile(backup, restore)
        if sha256_file(backup) != sha256_file(restore):
            raise FailClosed("restore byte copy mismatch")
        restore_con = apsw.Connection(str(restore), flags=apsw.SQLITE_OPEN_READWRITE)
        try:
            restore_before = self._logical_manifest(restore_con)
            restore_con.execute("CREATE TABLE __infra_restore_probe(token TEXT PRIMARY KEY) STRICT")
            token = sha256_text(str(time.time_ns()))
            restore_con.execute("INSERT INTO __infra_restore_probe VALUES(?)", (token,))
        finally:
            restore_con.close()
        reopened = apsw.Connection(str(restore), flags=apsw.SQLITE_OPEN_READWRITE)
        try:
            probe = reopened.execute("SELECT token FROM __infra_restore_probe").fetchone()
            restore_integrity = reopened.execute("PRAGMA integrity_check").fetchall()
        finally:
            reopened.close()
        same = source_before == source_after == backup_manifest == restore_before
        status = "PASS" if same and probe == (token,) and restore_integrity == [("ok",)] else "FAIL"
        return {"status": status, "method": "VACUUM INTO", "source_stable": source_before == source_after, "source_backup_equal": source_after == backup_manifest, "backup_restore_equal": backup_manifest == restore_before, "writable_restore_opened": True, "committed_probe_survived_reopen": probe == (token,), "restore_integrity_check": [row[0] for row in restore_integrity], "backup_path": str(backup), "restore_path": str(restore), "backup_sha256": sha256_file(backup), "manifest": backup_manifest}

    def migrate(self, migration_id: str, from_version: int, to_version: int, script_path: str | os.PathLike[str], evidence_dir: str | os.PathLike[str]) -> dict[str, Any]:
        if to_version != from_version + 1:
            raise FailClosed("migration must advance exactly one version")
        script = Path(script_path).read_text(encoding="utf-8")
        if "IF NOT EXISTS" in script.upper():
            raise FailClosed("migration scripts may not use IF NOT EXISTS")
        script_sha = sha256_text(script)
        evidence = Path(evidence_dir)
        evidence.mkdir(parents=True, exist_ok=True)
        pre = evidence / f"{migration_id}-pre.sqlite"
        post = evidence / f"{migration_id}-post.sqlite"
        if pre.exists() or post.exists():
            raise FailClosed("migration backup target already exists")
        with file_lock(self.lock_path, exclusive=True):
            con = self._open()
            try:
                current = con.execute("SELECT schema_version FROM schema_meta WHERE singleton=1").fetchone()[0]
                if current != from_version:
                    raise FailClosed(f"migration source version mismatch: {current}")
                if con.execute("SELECT 1 FROM migration_audit WHERE migration_id=?", (migration_id,)).fetchone():
                    raise FailClosed("migration id already used")
                if con.execute("PRAGMA integrity_check").fetchall() != [("ok",)]:
                    raise FailClosed("pre-migration integrity check failed")
                con.execute("BEGIN IMMEDIATE")
                con.execute("UPDATE maintenance_state SET active=1,migration_id=?,entered_at=?,reason=? WHERE singleton=1", (migration_id, utc_now(), f"schema {from_version}->{to_version}"))
                con.execute("COMMIT")
                con.execute("VACUUM INTO ?", (str(pre),))
                pre_check = apsw.Connection(str(pre)).execute("PRAGMA integrity_check").fetchall()
                if pre_check != [("ok",)]:
                    raise FailClosed("pre-migration backup integrity failed")
                pause_ready = os.environ.get("RESEARCHCTL_MIGRATION_READY_FILE")
                pause_release = os.environ.get("RESEARCHCTL_MIGRATION_RELEASE_FILE")
                if pause_ready:
                    Path(pause_ready).write_text("MAINTENANCE_EXCLUSIVE\n", encoding="utf-8")
                    while pause_release and not Path(pause_release).exists():
                        time.sleep(0.05)
                con.execute("BEGIN EXCLUSIVE")
                try:
                    observed = con.execute("SELECT schema_version FROM schema_meta WHERE singleton=1").fetchone()[0]
                    if observed != from_version:
                        raise FailClosed("schema changed after migration preflight")
                    con.execute(script)
                    con.execute("UPDATE schema_meta SET schema_version=? WHERE singleton=1", (to_version,))
                    con.execute(
                        "INSERT INTO migration_audit VALUES(?,?,?,?,?,?,?,?,?,?,?,?)",
                        (migration_id, from_version, to_version, script_sha, str(pre), str(post), "ok", "ok", utc_now(), WORKLOAD, "NONE", "NONE"),
                    )
                    con.execute("COMMIT")
                except BaseException:
                    if not con.getautocommit():
                        con.execute("ROLLBACK")
                    raise
                if con.execute("PRAGMA integrity_check").fetchall() != [("ok",)]:
                    raise FailClosed("post-migration integrity check failed")
                con.execute("VACUUM INTO ?", (str(post),))
                post_con = apsw.Connection(str(post))
                try:
                    post_check = post_con.execute("PRAGMA integrity_check").fetchall()
                    post_version = post_con.execute("SELECT schema_version FROM schema_meta WHERE singleton=1").fetchone()[0]
                finally:
                    post_con.close()
                if post_check != [("ok",)] or post_version != to_version:
                    raise FailClosed("post-migration backup verification failed")
                con.execute("BEGIN IMMEDIATE")
                con.execute("UPDATE maintenance_state SET active=0,migration_id=NULL,entered_at=NULL,reason=NULL WHERE singleton=1")
                con.execute("COMMIT")
                return {"status": "PASS", "migration_id": migration_id, "from_version": from_version, "to_version": to_version, "script_sha256": script_sha, "pre_backup": str(pre), "post_backup": str(post), "pre_integrity_check": "ok", "post_integrity_check": "ok", "maintenance_exited": True}
            finally:
                con.close()

"""P5 PC7 authority/amendment/trial runtime (engineering layer).

The daemon supplies ``peer_uid``, append-only sequence and canonical time.
Producer timestamps and payload role strings are never authorization inputs.
This module has no Research Memory write path; production persistence is the
separate, audited schema migration.
"""
from __future__ import annotations

from dataclasses import dataclass, field
from datetime import datetime, timezone
import hashlib
import json
from typing import Any, Callable


STATES = ("PROPOSED", "PRECONDITIONS_PASS", "HUMAN_OWNER_SIGNED", "APPLIED")
RUN_CLASSES = {"STATISTICAL_TRIAL", "SYNTHETIC_TEST"}


class AuthorityError(RuntimeError):
    pass


class AuthorizationDenied(AuthorityError):
    pass


class BindingMismatch(AuthorityError):
    pass


def canonical_json(value: Any) -> bytes:
    return json.dumps(value, ensure_ascii=False, sort_keys=True,
                      separators=(",", ":"), allow_nan=False).encode("utf-8")


def sha256(value: bytes) -> str:
    return hashlib.sha256(value).hexdigest()


def parse_utc(value: str) -> datetime:
    if not isinstance(value, str) or not value.endswith("Z"):
        raise AuthorityError("daemon time must be RFC3339 UTC")
    parsed = datetime.fromisoformat(value[:-1] + "+00:00")
    if parsed.utcoffset() != timezone.utc.utcoffset(parsed):
        raise AuthorityError("daemon time must be UTC")
    return parsed


@dataclass(frozen=True)
class FrozenBindings:
    family_id: str
    run_id: str
    run_class: str
    evidence_domain: str
    prereg_sha256: str
    dataset_manifest_sha256: str
    revision_lineage_sha256: str
    universe_rule_sha256: str
    validation_contract_sha256: str
    cost_contract: str
    evaluator_sha256: str
    cutoff: str
    wave_id: str | None = None
    candidate_grammar_sha256: str | None = None
    candidate_list_sha256: str | None = None
    candidate_count: int | None = None
    enumerator_sha256: str | None = None
    evaluation_order_sha256: str | None = None
    executable_contract_sha256: str | None = None
    risc_rule: str | None = None
    resource_scope: str | None = None

    def validate(self) -> "FrozenBindings":
        if self.run_class not in RUN_CLASSES:
            raise AuthorityError("unsupported run_class")
        for name, value in vars(self).items():
            if name.endswith("sha256") and value is not None:
                if len(value) != 64 or any(c not in "0123456789abcdef" for c in value):
                    raise AuthorityError(f"invalid {name}")
        if self.wave_id is not None:
            required = (self.wave_id, self.candidate_grammar_sha256,
                        self.candidate_list_sha256, self.enumerator_sha256,
                        self.evaluation_order_sha256,
                        self.executable_contract_sha256, self.risc_rule,
                        self.resource_scope)
            if any(value is None for value in required) or self.candidate_count != 174:
                raise AuthorityError("Wave-1 bindings incomplete")
        return self

    @property
    def digest(self) -> str:
        self.validate()
        return sha256(canonical_json(vars(self)))


@dataclass(frozen=True)
class DaemonContext:
    peer_uid: int
    session_id: str
    recorded_at: str
    ledger_sequence: int

    def validate(self) -> "DaemonContext":
        if not isinstance(self.peer_uid, int) or self.peer_uid < 0:
            raise AuthorityError("invalid daemon peer uid")
        if not self.session_id or not isinstance(self.ledger_sequence, int):
            raise AuthorityError("daemon session/order missing")
        parse_utc(self.recorded_at)
        return self


@dataclass
class AuthorityProposal:
    proposal_id: str
    bindings: FrozenBindings
    producer_session_id: str
    expires_at: str
    state: str = "PROPOSED"
    events: list[dict[str, Any]] = field(default_factory=list)
    applied_grant_id: str | None = None


class AuthorityFSM:
    """Fail-closed FSM whose trust inputs come only from the daemon."""

    def __init__(self, owner_peer_uid: int,
                 daemon_context: Callable[[], DaemonContext]):
        self._owner_peer_uid = owner_peer_uid
        self._daemon_context = daemon_context

    def _ctx(self) -> DaemonContext:
        return self._daemon_context().validate()

    def _append(self, proposal: AuthorityProposal, target: str,
                details: dict[str, Any]) -> None:
        current_index = STATES.index(proposal.state)
        if current_index + 1 >= len(STATES) or STATES[current_index + 1] != target:
            raise AuthorityError(f"illegal transition {proposal.state}->{target}")
        ctx = self._ctx()
        if proposal.events and ctx.ledger_sequence <= proposal.events[-1]["ledger_sequence"]:
            raise AuthorityError("daemon ledger order is not append-only")
        proposal.events.append({
            "from": proposal.state, "to": target,
            "daemon_recorded_at": ctx.recorded_at,
            "ledger_sequence": ctx.ledger_sequence,
            "immutable_session_id": ctx.session_id,
            "peer_uid": ctx.peer_uid,
            "details": details,
        })
        proposal.state = target

    def preconditions_pass(self, proposal: AuthorityProposal,
                           observed_binding_digest: str) -> None:
        if observed_binding_digest != proposal.bindings.digest:
            raise BindingMismatch("precondition binding digest mismatch")
        self._append(proposal, "PRECONDITIONS_PASS",
                     {"binding_digest": observed_binding_digest})

    def human_owner_sign(self, proposal: AuthorityProposal) -> None:
        ctx = self._ctx()
        if ctx.peer_uid != self._owner_peer_uid:
            raise AuthorizationDenied("HUMAN_OWNER_SIGNED requires owner daemon credential")
        if ctx.session_id == proposal.producer_session_id:
            raise AuthorizationDenied("owner session must differ from producer session")
        self._append(proposal, "HUMAN_OWNER_SIGNED",
                     {"owner_peer_uid": ctx.peer_uid})

    def apply(self, proposal: AuthorityProposal) -> str:
        ctx = self._ctx()
        if ctx.peer_uid != self._owner_peer_uid:
            raise AuthorizationDenied("APPLIED requires owner daemon credential")
        if parse_utc(ctx.recorded_at) >= parse_utc(proposal.expires_at):
            raise AuthorizationDenied("grant expired under daemon-authoritative time")
        grant_id = "grant-" + sha256(canonical_json({
            "proposal_id": proposal.proposal_id,
            "binding_digest": proposal.bindings.digest,
            "owner_session": ctx.session_id,
        }))[:32]
        self._append(proposal, "APPLIED", {"grant_id": grant_id})
        proposal.applied_grant_id = grant_id
        return grant_id


@dataclass
class Attempt:
    attempt_id: str
    logical_trial_id: str
    ordinal: int
    state: str = "RUNNING"


class TrialRegistry:
    """One logical wave per grant; infrastructure retries keep its identity."""

    def __init__(self) -> None:
        self._logical_by_grant: dict[str, tuple[str, str]] = {}
        self._attempts: dict[str, list[Attempt]] = {}

    def open_wave(self, grant_id: str, candidate_list_sha256: str) -> Attempt:
        existing = self._logical_by_grant.get(grant_id)
        if existing is None:
            logical = "logical-" + sha256(canonical_json(
                {"grant_id": grant_id, "candidate_list_sha256": candidate_list_sha256}))[:32]
            self._logical_by_grant[grant_id] = (logical, candidate_list_sha256)
            self._attempts[logical] = []
        else:
            logical, frozen_hash = existing
            if frozen_hash != candidate_list_sha256:
                raise BindingMismatch("new candidate list requires a new grant/wave")
        ordinal = len(self._attempts[logical]) + 1
        attempt = Attempt(f"{logical}-attempt-{ordinal:04d}", logical, ordinal)
        self._attempts[logical].append(attempt)
        return attempt

    def void_attempt(self, attempt: Attempt) -> None:
        if attempt.state != "RUNNING":
            raise AuthorityError("only running attempt can be voided")
        attempt.state = "ATTEMPT_VOID"

    def complete(self, attempt: Attempt) -> None:
        if attempt.state != "RUNNING":
            raise AuthorityError("only running attempt can complete")
        if any(a.state == "COMPLETED" for a in self._attempts[attempt.logical_trial_id]):
            raise AuthorityError("duplicate logical result")
        attempt.state = "COMPLETED"

    @property
    def logical_trial_count(self) -> int:
        return len(self._logical_by_grant)

